module example::vault {
    use sui::coin::{Self, Coin};
    use sui::sui::SUI;
    use sui::balance::{Self, Balance};

    public struct Vault has key {
        id: UID,
        balance: Balance<SUI>,
        admin: address,
    }

    fun init(ctx: &mut TxContext) {
        let vault = Vault {
            id: object::new(ctx),
            balance: balance::zero(),
            admin: ctx.sender(),
        };
        transfer::share_object(vault);
    }

    public fun deposit(vault: &mut Vault, coin: Coin<SUI>) {
        coin::put(&mut vault.balance, coin);
    }

    public fun withdraw(vault: &mut Vault, amount: u64, ctx: &mut TxContext): Coin<SUI> {
        assert!(ctx.sender() == vault.admin, 0);
        coin::take(&mut vault.balance, amount, ctx)
    }

    public fun change_admin(vault: &mut Vault, new_admin: address, ctx: &mut TxContext) {
        assert!(ctx.sender() == vault.admin, 0);
        vault.admin = new_admin;
    }
}
